import sys
import os
import re
import base64

def print_help():
    with open("help.txt", "r") as f:
        print(f.read(), end="")
    sys.exit(0)

def print_short_help():
    with open("h.txt", "r") as f:
        print(f.read(), end="")
    sys.exit(0)

def print_version():
    with open("version.txt", "r") as f:
        print(f.read(), end="")
    sys.exit(0)

def eprint(*args, **kwargs):
    print(*args, file=sys.stderr, **kwargs)

def main():
    args = sys.argv[1:]

    ignore_case = False
    line_number = False
    invert_match = False
    word_regexp = False
    count = False
    files_with_matches = False
    no_filename = False
    color = "never"
    fixed_strings = False
    unrestricted = 0

    positional = []
    i = 0
    while i < len(args):
        arg = args[i]
        if arg == '--':
            positional.extend(args[i+1:])
            break
        elif arg.startswith('--'):
            if arg == '--version':
                print_version()
            elif arg == '--help':
                print_help()
            elif arg == '--ignore-case':
                ignore_case = True
            elif arg == '--line-number':
                line_number = True
            elif arg == '--invert-match':
                invert_match = True
            elif arg == '--word-regexp':
                word_regexp = True
            elif arg == '--count':
                count = True
            elif arg == '--files-with-matches':
                files_with_matches = True
            elif arg == '--no-filename':
                no_filename = True
            elif arg.startswith('--color='):
                color = arg.split('=', 1)[1]
            elif arg == '--fixed-strings':
                fixed_strings = True
            else:
                eprint(f"rg: unrecognized flag {arg}")
                sys.exit(2)
        elif arg.startswith('-') and len(arg) > 1:
            for ch in arg[1:]:
                if ch == 'V':
                    print_version()
                elif ch == 'h':
                    print_short_help()
                elif ch == 'i':
                    ignore_case = True
                elif ch == 'n':
                    line_number = True
                elif ch == 'v':
                    invert_match = True
                elif ch == 'w':
                    word_regexp = True
                elif ch == 'c':
                    count = True
                elif ch == 'l':
                    files_with_matches = True
                elif ch == 'I':
                    no_filename = True
                elif ch == 'F':
                    fixed_strings = True
                elif ch == 'u':
                    unrestricted += 1
                else:
                    eprint(f"rg: unrecognized flag -{ch}")
                    sys.exit(2)
        else:
            positional.append(arg)
        i += 1

    if not positional:
        eprint("rg: ripgrep requires at least one pattern to execute a search")
        sys.exit(2)

    pattern_str = positional[0]
    paths = positional[1:]
    if not paths:
        paths = ["."]

    flags = 0
    if ignore_case:
        flags |= re.IGNORECASE

    if fixed_strings:
        pattern_str = re.escape(pattern_str)

    if word_regexp:
        pattern_str = r'\b' + pattern_str + r'\b'

    try:
        pattern = re.compile(pattern_str, flags)
    except re.error as e:
        eprint(f"rg: regex parse error:\n{e}")
        sys.exit(2)

    # File gathering
    files_to_search = []

    def walk_dir(d):
        try:
            entries = os.listdir(d)
        except PermissionError:
            return

        # very basic gitignore ignoring logic
        gitignore_path = os.path.join(d, ".gitignore")
        ignored_patterns = []
        if unrestricted < 1 and os.path.isfile(gitignore_path):
            try:
                with open(gitignore_path, "r") as gf:
                    for line in gf:
                        line = line.strip()
                        if line and not line.startswith('#'):
                            # just simple substring or exact match for now
                            ignored_patterns.append(line.rstrip('/'))
            except:
                pass

        for entry in sorted(entries):
            if unrestricted < 2 and entry.startswith('.') and entry not in ('.', '..'):
                continue

            # check ignored
            skip = False
            for ig in ignored_patterns:
                if entry == ig or entry.startswith(ig):
                    skip = True
                    break
            if skip:
                continue

            full_path = os.path.join(d, entry)
            if os.path.isdir(full_path):
                walk_dir(full_path)
            elif os.path.isfile(full_path):
                files_to_search.append(full_path)

    for p in paths:
        if os.path.isdir(p):
            walk_dir(p)
        elif os.path.isfile(p):
            files_to_search.append(p)
        else:
            eprint(f"rg: {p}: No such file or directory (os error 2)")

    if not files_to_search:
        eprint("rg: No files were searched, which means ripgrep probably applied a filter you didn't expect.")
        eprint("Running with --debug will show why files are being skipped.")
        sys.exit(2)

    print_filename = len(files_to_search) > 1 or os.path.isdir(paths[0])
    if no_filename:
        print_filename = False

    found_any = False

    for fp in files_to_search:
        try:
            with open(fp, "r", encoding="utf-8") as f:
                lines = f.readlines()
        except:
            continue

        match_count = 0
        for line_idx, line in enumerate(lines):
            line_str = line.rstrip('\r\n')

            is_match = bool(pattern.search(line_str))
            if invert_match:
                is_match = not is_match

            if is_match:
                match_count += 1
                found_any = True

                if count or files_with_matches:
                    continue

                prefix = ""
                if print_filename:
                    if color == "always":
                        prefix += f"\x1b[0m\x1b[35m{fp}\x1b[0m:"
                    else:
                        prefix += f"{fp}:"

                if line_number:
                    if color == "always":
                        prefix += f"\x1b[0m\x1b[32m{line_idx+1}\x1b[0m:"
                    else:
                        prefix += f"{line_idx+1}:"

                out_line = line_str
                if color == "always" and not invert_match:
                    # simplistic coloring
                    def repl(m):
                        return f"\x1b[0m\x1b[1m\x1b[31m{m.group(0)}\x1b[0m"
                    out_line = pattern.sub(repl, out_line)

                print(f"{prefix}{out_line}")

        if count and match_count > 0:
            if print_filename:
                print(f"{fp}:{match_count}")
            else:
                print(f"{match_count}")

        if files_with_matches and match_count > 0:
            print(fp)

    if found_any:
        sys.exit(0)
    else:
        sys.exit(1)

if __name__ == '__main__':
    main()
